export function getUrlForExpression(name: string, expression: string) {
  // Ensure the name is valid and has at least one character
  if (!name || name.length === 0) {
    throw new Error('Name must be provided and cannot be empty')
  }

  // List of valid expressions
  const validExpressions = [
    'neutral',
    'happy',
    'very happy',
    'disgusted',
    'very disgusted',
    'mad',
    'enraged',
    'sad',
    'crying',
    'smirking',
    'smug',
    'fond',
    'deeply in love',
    'lustful',
    'intensely desirous',
  ]

  // Convert the first letter of the name to uppercase
  const firstLetter = name[0].toUpperCase()

  // Check if expression is valid, default to 'neutral' if not
  expression = validExpressions.includes(expression) ? expression : 'neutral'

  // Determine the range based on the first letter and return the URL
  if (firstLetter >= 'A' && firstLetter <= 'I') {
    return `https://aiu-character.s3.amazonaws.com/Ayla/ayla_${expression}.png`
  }
  else if (firstLetter >= 'J' && firstLetter <= 'R') {
    return `https://aiu-character.s3.amazonaws.com/Bern/bern_${expression}.png`
  }
  else if (firstLetter >= 'S' && firstLetter <= 'Z') {
    return `https://aiu-character.s3.amazonaws.com/Dimitri/dimitri_${expression}.png`
  }
  else {
    // Handle cases where the first letter is not a standard alphabet letter
    throw new Error('Name must start with a standard alphabet letter (A-Z)')
  }
}

const audioUrls = [
  'https://actions.google.com/sounds/v1/alarms/beep_short.ogg',
  'https://actions.google.com/sounds/v1/alarms/bugle_tune.ogg',
  'https://actions.google.com/sounds/v1/alarms/radiation_meter.ogg',
]

export function getRandomAudioUrl() {
  const randomIndex = Math.floor(Math.random() * audioUrls.length)
  return audioUrls[randomIndex]
}

